      SUBROUTINE TWITCHCC     ADVANCES PARTIAL DERIVATIVE OF TRANSFER MATRIX ABOUT DISPLACEDC     ORBITCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM7D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'ETATC.CIN'      INCLUDE 'R2P.CIN'CC     CONTRIBUTION TO DERIVATIVE OF FIRST-ORDER MATRIX OFC     INDIVIDUAL ELEMENT FROM DERIVATIVE OF REFERENCE TRAJECTORYC     DISPLACEMENT USING SHIFTED REFERENCEC      IF (.NOT. CVP(NV2)) GO TO 100      IF (NORD1 .GE. 2) CALL TWIT2R      IF (NORD1 .GE. 3) CALL TWIT3R      IF (NORD1 .GE. 2) R2VP(NV2) = .TRUE.CC     TRANSFORM DERIVATIVE OF REFERENCE TRAJECTORY DISPLACEMENTC      CALL TWIT1C      IF (NORD1 .GE. 2) CALL TWIT2C      IF (NORD1 .GE. 3) CALL TWIT3C      DO 10 J = 1, 6   10 COV(J,NV2) = COT(J)CC     TRANSFORM DERIVATIVE OF ETAC  100 IF (EVP(NV2)) THEN        CALL TWIT1E        IF (NORD1 .GE. 2) CALL TWIT2E        IF (NORD1 .GE. 3) CALL TWIT3E        DO 110 J = 1, 6  110   ETAV(J,NV2) = ETAT(J)      ENDIFC  200 RETURN      END